// Samenvoegen: orders (Shopify) + sessies + ad spend/clicks (Airtable Systeem 3)
// Per campagne: sessions, orders, revenue, spend, clicks => CR, CPA, ROAS, Flag
//
// Flag logica:
//   - clicks > 50 AND orders == 0 in last 24u => 'Clicks No Conversion'
//   - CPA > 15 EUR => 'High CPA'
//   - CR < 0.01 AND sessions > 100 => 'Low CR'
//   - Cart Abandonment > 0.85 AND ATC > 20 => 'High Abandonment'
//   - else => 'OK'

const shopifyOrders = items[0].json.orders || [];
const adVariants = items[2].json.records || [];

// Groep orders per campagne via UTM of landing page referer
const byCampaign = {};
for (const order of shopifyOrders) {
  const utm = (order.note_attributes || []).find(n => n.name === 'utm_campaign')?.value || 'direct';
  if (!byCampaign[utm]) byCampaign[utm] = { orders: 0, revenue: 0, items: [] };
  byCampaign[utm].orders += 1;
  byCampaign[utm].revenue += parseFloat(order.total_price || 0);
  byCampaign[utm].items.push(order.line_items?.map(li => li.title).join(', '));
}

// Aggregate ad spend per campagne
const adByCampaign = {};
for (const variant of adVariants) {
  const f = variant.fields;
  const campaignLink = f.Campaign?.[0] || 'unknown';
  if (!adByCampaign[campaignLink]) adByCampaign[campaignLink] = { spend: 0, clicks: 0, impressions: 0 };
  adByCampaign[campaignLink].spend += parseFloat(f.Spend || 0);
  adByCampaign[campaignLink].clicks += parseInt(f.Clicks || 0);
  adByCampaign[campaignLink].impressions += parseInt(f.Impressions || 0);
}

const results = [];
const allCampaigns = new Set([...Object.keys(byCampaign), ...Object.keys(adByCampaign)]);
for (const camp of allCampaigns) {
  const orderData = byCampaign[camp] || { orders: 0, revenue: 0 };
  const adData = adByCampaign[camp] || { spend: 0, clicks: 0, impressions: 0 };
  const sessions = adData.clicks; // proxy, exacte sessies via Shopify Analytics later
  const cr = sessions > 0 ? orderData.orders / sessions : 0;
  const cpa = orderData.orders > 0 ? adData.spend / orderData.orders : null;
  const roas = adData.spend > 0 ? orderData.revenue / adData.spend : null;

  let flag = 'OK';
  if (adData.clicks > 50 && orderData.orders === 0) flag = 'Clicks No Conversion';
  else if (cpa !== null && cpa > 15) flag = 'High CPA';
  else if (sessions > 100 && cr < 0.01) flag = 'Low CR';

  results.push({
    json: {
      Date: new Date().toISOString().split('T')[0],
      Campaign_ID: camp,
      Channel: camp === 'direct' ? 'Direct' : 'Meta Ads',
      Sessions: sessions,
      Orders: orderData.orders,
      Revenue: orderData.revenue,
      Ad_Spend: adData.spend,
      CPA: cpa,
      ROAS: roas,
      Flag: flag,
      Conversion_Rate: cr
    }
  });
}

return results;

